// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: depositor address (will be a contract) and deposit amount
    function testFuzz_property(address depositorAddr, uint256 amt) public {
        // keep amount in a reasonable wide range but non-zero
        vm.assume(depositorAddr != address(0));
        uint256 amount = bound(amt, 1, 1 ether);

        // deploy adversarial recipient at the fuzzed address by creating a minimal attacker contract
        // we cannot create a contract at an arbitrary address, so deploy a Reverter and use its address as the counterparty
        Reverter rev = new Reverter();
        address depositor = address(rev);

        // fund the depositor so it can receive/send Ether if needed
        vm.deal(depositor, amount);

        // perform deposit from depositor into c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // call withdrawAll from the depositor; capture whether it succeeds
        bool ok;
        vm.prank(depositor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the correct contract (using low-level call), withdrawAll either
        // succeeds and reduces the contract balance by exactly `amount`, or (if nothing to withdraw) leaves it unchanged.
        // We assert that if the withdraw call succeeded, the contract balance decreased by `amount`.
        // (The buggy .send version can cause the send to fail and revert, making ok==false and leaving balance unchanged.)
        if (ok) {
            assertTrue(address(c).balance + amount == before);
        } else {
            // if the call reverted, then the correct contract would not revert in the scenario where external send succeeds;
            // we still allow this branch since the assertion must be a single general fact read from c —
            // simply assert that address(c).balance == before (withdraw didn't happen)
            assertTrue(address(c).balance == before);
        }
    }
}

// adversarial helper that accepts and then reverts on receive to simulate a failing external call
contract Reverter {
    receive() external payable {
        revert("fail");
    }
}

