pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount within reasonable bounds but wide
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // deploy an adversarial recipient that will *reject* incoming Ether by returning false when called
        RejectingRecipient rejector = new RejectingRecipient();

        // fund the depositor and make them deposit into c
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Sanity: c should have balance == amount
        uint256 before = address(c).balance;
        // now set msg.sender to the depositor and set their credit (already set by deposit)
        vm.prank(depositor);
        // Instead of calling withdrawAll as depositor directly to their EOA, we make the depositor be the rejector
        // by having the rejector act as depositor: first, we transfer credit to the rejector by calling deposit from rejector
        // (we need the credited address to be the one that will receive the call). So perform a deposit from rejector
        vm.deal(address(rejector), amount);
        vm.prank(address(rejector));
        c.deposit{value: amount}();

        // Confirm the contract has the expected balance
        uint256 mid = address(c).balance;
        assertTrue(mid >= before);

        // Now attempt withdrawAll as the rejecting recipient. The correct contract using .call would succeed
        // (the recipient's fallback can accept or revert, but .call returns the callee's success). The mutation
        // to .send returns false when the recipient's receive() uses more gas or explicitly fails; that makes
        // withdrawAll revert in the mutant for some recipients. We detect that by calling withdrawAll and
        // observing whether it returned (ok == true). The universal property: for all depositor/amount/rejector,
        // the reference C will complete withdrawAll call (ok == true) and contract balance will decrease by amount.

        // Call withdrawAll and capture whether it succeeded (did not revert)
        bool ok;
        vm.prank(address(rejector));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assert: the reference contract (with .call) must always succeed withdrawAll when the credited
        // recipient is a contract that has a payable fallback (even if it reverts), so ok should be true for the
        // reference; the mutant using .send will sometimes cause ok == false and thus fail this assertion.
        assertTrue(ok);
    }
}

// Adversarial helper: this recipient will deliberately revert in its fallback/receive to cause .send to fail
contract RejectingRecipient {
    // accept no data, revert on receive to simulate a callee that fails to accept the funds
    receive() external payable {
        // revert to cause .send to return false (or cause .call to return false depending on gas);
        revert("reject");
    }
}

