pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: depositor and deposit amount
    // We deploy an adversarial helper that is a contract which will on receive() try to consume gas
    // and then return/stop, causing .send() to possibly fail while .call() would forward gas.
    function testFuzz_property(address depositor, uint256 amount) public {
        // admissible domain: depositor must be non-zero and amount in a reasonable range and > 0
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether); // keep wide but exclude zero

        // Fund the depositor EOA so it can deposit
        vm.deal(depositor, amount);

        // Deploy an adversarial recipient that will be the msg.sender when withdrawAll sends funds.
        // This helper will have a receive() that consumes a lot of gas and then returns (not revert),
        // which can cause .send to fail (due to stipend) while .call would succeed.
        GasConsumingReceiver receiver = new GasConsumingReceiver();

        // depositor deposits into c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Now we want withdrawAll to be executed with msg.sender == receiver so c will attempt to send
        // Ether to receiver. To simulate that, we have receiver call c.withdrawAll() (it will be the recipient
        // of the send/call). We need to fund receiver so it can make the external call gas cost.
        vm.deal(address(receiver), 1 ether);

        bool ok;
        try receiver.callWithdraw(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: On the correct reference implementation (which this test is run against),
        // withdrawAll should succeed (not revert) for all admissible inputs (depositor != 0 and amount > 0)
        // even when the recipient's fallback consumes gas. The mutant using .send can fail for some inputs.
        assertTrue(ok);
    }
}

// adversarial helper: consumes a large amount of gas in receive to trigger stipend failure for .send
contract GasConsumingReceiver {
    // allow external funding
    receive() external payable {
        // consume a lot of gas in a loop; bounded so it won't run forever but will consume significant gas
        // to make .send likely return false while .call would still succeed if more gas forwarded.
        for (uint i = 0; i < 2000; i++) {
            // some no-op to consume gas
            uint x = i * i;
            x;
        }
    }

    // helper that calls withdrawAll on target c so that this contract is the recipient of the external send
    function callWithdraw(address target) external returns (bool) {
        C t = C(payable(target));
        t.withdrawAll();
        return true;
    }
}

