pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount to deposit (and then withdraw) and an index to pick whether caller is adversarial
    function testFuzz_property(uint256 amount, uint256 adversarySelector) public {
        // keep amount in a reasonable wide but non-zero domain
        vm.assume(amount > 0 && amount <= 1 ether);

        // deploy an adversarial callee that reverts on receive to distinguish call vs transfer
        Reverter r = new Reverter();

        // choose actor: either EOA (address(this)) or the reverter contract
        address actor = (adversarySelector % 2 == 0) ? address(this) : address(r);

        // fund the actor so it can deposit
        vm.deal(actor, amount + 1);

        // perform deposit from that actor
        if (actor == address(this)) {
            // deposit as this contract
            c.deposit{value: amount}();
        } else {
            // deposit from the reverter contract
            vm.prank(address(r));
            // the reverter contract has a payable deposit caller; call c.deposit with value
            r.callDeposit{value: amount}(address(c));
        }

        // Now attempt to withdrawAll as that actor and observe whether the call completes
        bool ok;
        if (actor == address(this)) {
            // withdraw as this contract
            try c.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // have the reverter contract call withdrawAll on c
            try r.callWithdraw(address(c)) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // General property: on the reference C (which uses low-level call and checks the boolean), withdrawAll should always complete (not revert) for any caller and any deposited amount.
        // The mutant that uses transfer will revert when the recipient reverts; hence for some inputs (adversarial recipient) ok==false for the mutant but true for reference.
        assertTrue(ok);
    }
}

