        try reverter.callWithdraw(address(c)) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // The general invariant we assert (single assert): after a failed external send from c to the caller, the contract's balance must equal the sum of all recorded credits for that caller plus any other stored amounts; specifically, address(c).balance should be >= 0 and remain consistent (we observe that for the correct contract a failing send leaves the recorded credit intact and balance unchanged). Here we assert that if the external call failed (succeeded == false) then address(c).balance >= 0 (trivially true) but more importantly that the c contract's balance is not less than zero (observational).
        // To make a meaningful single assertion that the reference satisfies for all inputs but the mutant violates for some inputs, we check that when the withdraw attempt failed, the contract's balance is equal to the recorded mapping credit for the reverter (i.e., deposit was not lost). The reference preserves credit and balance matching; the mutant can lose that relationship.

        // There's no direct getter for credit mapping; but we can observe address(c).balance which for the correct contract after a failed send should still hold the deposited funds (since funds weren't forwarded out). Therefore we assert that when the withdraw attempt failed, address(c).balance == amt.
        // This is a single assertTrue reading c via address(c).balance.

        if (!succeeded) {
            // For the correct contract this must hold for all admissible inputs; the mutant will have cases where it fails.
            assertTrue(address(c).balance == amt);
        } else {
            // If withdraw succeeded, then balance will be 0; still a valid state — assertTrue of a tautology reading c: balance is either 0 or amt
            assertTrue(address(c).balance == 0 || address(c).balance == amt);
        }
    }
}

// Adversarial helper that reverts on receive, and can deposit/withdraw via C
contract ReceiveReverter {
    // reject any incoming payments to cause low-level call from C to revert
    receive() external payable {
        revert("revert on receive");
    }

    // helper to deposit into C
    function depositTo(address c) external payable {
        C(c).deposit{value: address(this).balance}();
    }

    // helper to call withdrawAll on C
    function callWithdraw(address c) external {
        C(c).withdrawAll();
    }
}

