pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep depositor non-zero and amount in a reasonable range (non-zero, and not exceeding eth limit)
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // Deploy an adversarial helper that WILL revert on receiving funds
        Reverter rev = new Reverter();

        // Fund depositor so they can deposit
        vm.deal(depositor, amount);

        // Make depositor deposit into c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Now set depositor's credit to be the reverter contract address by making the reverter act as depositor
        // We need the withdrawAll caller to be the reverter so that the low-level call to msg.sender during withdrawAll will revert.
        // To do that, have the reverter previously receive credit by performing the deposit from the reverter address.
        vm.deal(address(rev), amount);
        vm.prank(address(rev));
        c.deposit{value: amount}();

        // Now, call withdrawAll from the reverter so its fallback will revert when the contract tries to send value.
        bool ok;
        try ReverterCaller(address(rev)).callWithdraw(address(c)) returns (bool res) {
            ok = res;
        } catch {
            // if the call itself reverts, mark as false
            ok = false;
        }

        // The universal property we assert: after a failing external call during withdrawAll, the reference C preserves the recorded credit for that caller (i.e., withdrawAll did not clear credit when the external transfer reverted).
        // We observe this by attempting to read the credit via a second withdrawAll: for the correct contract, the second withdrawAll should also attempt to send value and thus will also revert (so ok==false), meaning credit remained and behavior shows failure again.
        // If the mutant had cleared credit before the external call and the external call reverted, then credit would be zero and a subsequent withdrawAll would be a no-op (succeed/return) -> ok==true.

        // Therefore assert that withdrawAll from reverter still fails (ok == false) which the reference guarantees for all admissible inputs; the mutant can make this true->false.
        assertTrue(ok == false);
    }
}

// Helper that reverts on receive/call
contract Reverter {
    // receive will revert so that low-level call from C fails
    receive() external payable {
        revert("revert receive");
    }
}

// Small caller deployed at the same address as Reverter but provides a function to call c.withdrawAll from that address.
// We use this to perform the withdrawAll inside a try/catch in the test.
contract ReverterCaller {
    function callWithdraw(address cAddr) external returns (bool) {
        (bool ok, ) = cAddr.call(abi.encodeWithSignature("withdrawAll()"));
        if (!ok) revert("withdraw failed");
        return ok;
    }
}
